=head1 MESSAGES

=head2 Google::Cloud::Video::Transcoder::V1::Resources::Job

Transcoding job resource.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

The resource name of the job.
Format: `projects/{project_number}/locations/{location}/jobs/{job}`

=item * C<< $msg->input_uri() >> / C<< $msg->input_uri($value) >>

Type: C<String>

Input only. Specify the `input_uri` to populate empty `uri` fields in each
element of `Job.config.inputs` or `JobTemplate.config.inputs` when using
template. URI of the media. Input files must be at least 5 seconds in
duration and stored in Cloud Storage (for example,
`gs://bucket/inputs/file.mp4`). See [Supported input and output
formats](https://cloud.google.com/transcoder/docs/concepts/supported-input-and-output-formats).

=item * C<< $msg->output_uri() >> / C<< $msg->output_uri($value) >>

Type: C<String>

Input only. Specify the `output_uri` to populate an empty
`Job.config.output.uri` or `JobTemplate.config.output.uri` when using
template. URI for the output file(s). For example,
`gs://my-bucket/outputs/`. See [Supported input and output
formats](https://cloud.google.com/transcoder/docs/concepts/supported-input-and-output-formats).

=item * C<< $msg->template_id() >> / C<< $msg->template_id($value) >>

Type: C<String>

Input only. Specify the `template_id` to use for populating `Job.config`.
The default is `preset/web-hd`, which is the only supported preset.

User defined JobTemplate: `{job_template_id}`

=item * C<< $msg->config() >> / C<< $msg->config($value) >>

Type: C<Message> (L<Google::Cloud::Video::Transcoder::V1::Resources::JobConfig>)

The configuration for this job.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Video::Transcoder::V1::Job::ProcessingState>)

Output only. The current state of the job.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time the job was created.

=item * C<< $msg->start_time() >> / C<< $msg->start_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time the transcoding started.

=item * C<< $msg->end_time() >> / C<< $msg->end_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time the transcoding finished.

=item * C<< $msg->ttl_after_completion_days() >> / C<< $msg->ttl_after_completion_days($value) >>

Type: C<Int32>

Job time to live value in days, which will be effective after job
completion. Job should be deleted automatically after the given TTL. Enter
a value between 1 and 90. The default is 30.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Video::Transcoder::V1::Resources::Job::LabelsEntry>)

The labels associated with this job. You can use these to organize and
group your jobs.

=item * C<< $msg->error() >> / C<< $msg->error($value) >>

Type: C<Message> (L<Google::Rpc::Status::Status>)

Output only. An error object that describes the reason for the failure.
This property is always present when
[ProcessingState][google.cloud.video.transcoder.v1.Job.ProcessingState] is
`FAILED`.

=item * C<< $msg->mode() >> / C<< $msg->mode($value) >>

Type: C<Enum> (L<Google::Cloud::Video::Transcoder::V1::Job::ProcessingMode>)

The processing mode of the job.
The default is `PROCESSING_MODE_INTERACTIVE`.

=item * C<< $msg->batch_mode_priority() >> / C<< $msg->batch_mode_priority($value) >>

Type: C<Int32>

The processing priority of a batch job.
This field can only be set for batch mode jobs. The default value is 0.
This value cannot be negative. Higher values correspond to higher
priorities for the job.

=item * C<< $msg->optimization() >> / C<< $msg->optimization($value) >>

Type: C<Enum> (L<Google::Cloud::Video::Transcoder::V1::Job::OptimizationStrategy>)

Optional. The optimization strategy of the job. The default is
`AUTODETECT`.

=item * C<< $msg->fill_content_gaps() >> / C<< $msg->fill_content_gaps($value) >>

Type: C<Bool>

Optional. Insert silence and duplicate frames when timestamp gaps are
detected in a given stream.

=back

