=head2 Google::Cloud::Video::Transcoder::V1::Resources::Input

Input asset.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->key() >> / C<< $msg->key($value) >>

Type: C<String>

A unique key for this input. Must be specified when using advanced
mapping and edit lists.

=item * C<< $msg->uri() >> / C<< $msg->uri($value) >>

Type: C<String>

URI of the media. Input files must be at least 5 seconds in duration and
stored in Cloud Storage (for example, `gs://bucket/inputs/file.mp4`).
If empty, the value is populated from
[Job.input_uri][google.cloud.video.transcoder.v1.Job.input_uri]. See
[Supported input and output
formats](https://cloud.google.com/transcoder/docs/concepts/supported-input-and-output-formats).

=item * C<< $msg->preprocessing_config() >> / C<< $msg->preprocessing_config($value) >>

Type: C<Message> (L<Google::Cloud::Video::Transcoder::V1::Resources::PreprocessingConfig>)

Preprocessing configurations.

=item * C<< $msg->attributes() >> / C<< $msg->attributes($value) >>

Type: C<Message> (L<Google::Cloud::Video::Transcoder::V1::Resources::InputAttributes>)

Optional. Input Attributes.

=back

=head2 Google::Cloud::Video::Transcoder::V1::Resources::Output

Location of output file(s) in a Cloud Storage bucket.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->uri() >> / C<< $msg->uri($value) >>

Type: C<String>

URI for the output file(s). For example, `gs://my-bucket/outputs/`. Must be
a directory and not a top-level bucket. If empty, the value is populated
from [Job.output_uri][google.cloud.video.transcoder.v1.Job.output_uri]. See
[Supported input and output
formats](https://cloud.google.com/transcoder/docs/concepts/supported-input-and-output-formats).

=back

=head2 Google::Cloud::Video::Transcoder::V1::Resources::EditAtom

Edit atom.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->key() >> / C<< $msg->key($value) >>

Type: C<String>

A unique key for this atom. Must be specified when using advanced
mapping.

=item * C<< $msg->inputs() >> / C<< $msg->inputs($value) >>

Type: C<String>

List of [Input.key][google.cloud.video.transcoder.v1.Input.key] values
identifying files that should be used in this atom. The listed `inputs`
must have the same timeline.

=item * C<< $msg->end_time_offset() >> / C<< $msg->end_time_offset($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

End time in seconds for the atom, relative to the input file timeline.
When `end_time_offset` is not specified, the `inputs` are used until
the end of the atom.

=item * C<< $msg->start_time_offset() >> / C<< $msg->start_time_offset($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

Start time in seconds for the atom, relative to the input file timeline.
The default is `0s`.

=back

