=head2 Google::Cloud::Video::Transcoder::V1::Resources::MuxStream

Multiplexing settings for output stream.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->key() >> / C<< $msg->key($value) >>

Type: C<String>

A unique key for this multiplexed stream.

=item * C<< $msg->file_name() >> / C<< $msg->file_name($value) >>

Type: C<String>

The name of the generated file. The default is
[MuxStream.key][google.cloud.video.transcoder.v1.MuxStream.key] with the
extension suffix corresponding to the
[MuxStream.container][google.cloud.video.transcoder.v1.MuxStream.container].

Individual segments also have an incremental 10-digit zero-padded suffix
starting from 0 before the extension, such as `mux_stream0000000123.ts`.

=item * C<< $msg->container() >> / C<< $msg->container($value) >>

Type: C<String>

The container format. The default is `mp4`

Supported streaming formats:

- `ts`
- `fmp4`- the corresponding file extension is `.m4s`

Supported standalone file formats:

- `mp4`
- `mp3`
- `ogg`
- `vtt`

See also:
[Supported input and output
formats](https://cloud.google.com/transcoder/docs/concepts/supported-input-and-output-formats)

=item * C<< $msg->elementary_streams() >> / C<< $msg->elementary_streams($value) >>

Type: C<String>

List of
[ElementaryStream.key][google.cloud.video.transcoder.v1.ElementaryStream.key]
values multiplexed in this stream.

=item * C<< $msg->segment_settings() >> / C<< $msg->segment_settings($value) >>

Type: C<Message> (L<Google::Cloud::Video::Transcoder::V1::Resources::SegmentSettings>)

Segment settings for `ts`, `fmp4` and `vtt`.

=item * C<< $msg->encryption_id() >> / C<< $msg->encryption_id($value) >>

Type: C<String>

Identifier of the encryption configuration to use. If omitted, output will
be unencrypted.

=item * C<< $msg->fmp4() >> / C<< $msg->fmp4($value) >>

Type: C<Message> (L<Google::Cloud::Video::Transcoder::V1::Resources::MuxStream::Fmp4Config>)

Optional. `fmp4` container configuration.

=back

=head2 Google::Cloud::Video::Transcoder::V1::Resources::Manifest

Manifest configuration.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->file_name() >> / C<< $msg->file_name($value) >>

Type: C<String>

The name of the generated file. The default is `manifest` with the
extension suffix corresponding to the
[Manifest.type][google.cloud.video.transcoder.v1.Manifest.type].

=item * C<< $msg->type() >> / C<< $msg->type($value) >>

Type: C<Enum> (L<Google::Cloud::Video::Transcoder::V1::Manifest::ManifestType>)

Required. Type of the manifest.

=item * C<< $msg->mux_streams() >> / C<< $msg->mux_streams($value) >>

Type: C<String>

Required. List of user supplied
[MuxStream.key][google.cloud.video.transcoder.v1.MuxStream.key] values that
should appear in this manifest.

When [Manifest.type][google.cloud.video.transcoder.v1.Manifest.type] is
`HLS`, a media manifest with name
[MuxStream.key][google.cloud.video.transcoder.v1.MuxStream.key] and `.m3u8`
extension is generated for each element in this list.

=item * C<< $msg->dash() >> / C<< $msg->dash($value) >>

Type: C<Message> (L<Google::Cloud::Video::Transcoder::V1::Resources::Manifest::DashConfig>)

`DASH` manifest configuration.

=back

=head3 Enum: Manifest::ManifestType

=over 4

=item * C<MANIFEST_TYPE_UNSPECIFIED> => C<0>

=item * C<HLS> => C<1>

=item * C<DASH> => C<2>

=back

=head2 Google::Cloud::Video::Transcoder::V1::Resources::PubsubDestination

A Pub/Sub destination.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->topic() >> / C<< $msg->topic($value) >>

Type: C<String>

The name of the Pub/Sub topic to publish job completion notification
to. For example: `projects/{project}/topics/{topic}`.

=back

=head2 Google::Cloud::Video::Transcoder::V1::Resources::SpriteSheet

Sprite sheet configuration.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->format() >> / C<< $msg->format($value) >>

Type: C<String>

Format type. The default is `jpeg`.

Supported formats:

- `jpeg`

=item * C<< $msg->file_prefix() >> / C<< $msg->file_prefix($value) >>

Type: C<String>

Required. File name prefix for the generated sprite sheets.

Each sprite sheet has an incremental 10-digit zero-padded suffix starting
from 0 before the extension, such as `sprite_sheet0000000123.jpeg`.

=item * C<< $msg->sprite_width_pixels() >> / C<< $msg->sprite_width_pixels($value) >>

Type: C<Int32>

Required. The width of sprite in pixels. Must be an even integer. To
preserve the source aspect ratio, set the
[SpriteSheet.sprite_width_pixels][google.cloud.video.transcoder.v1.SpriteSheet.sprite_width_pixels]
field or the
[SpriteSheet.sprite_height_pixels][google.cloud.video.transcoder.v1.SpriteSheet.sprite_height_pixels]
field, but not both (the API will automatically calculate the missing
field).

For portrait videos that contain horizontal ASR and rotation metadata,
provide the width, in pixels, per the horizontal ASR. The API calculates
the height per the horizontal ASR. The API detects any rotation metadata
and swaps the requested height and width for the output.

=item * C<< $msg->sprite_height_pixels() >> / C<< $msg->sprite_height_pixels($value) >>

Type: C<Int32>

Required. The height of sprite in pixels. Must be an even integer. To
preserve the source aspect ratio, set the
[SpriteSheet.sprite_height_pixels][google.cloud.video.transcoder.v1.SpriteSheet.sprite_height_pixels]
field or the
[SpriteSheet.sprite_width_pixels][google.cloud.video.transcoder.v1.SpriteSheet.sprite_width_pixels]
field, but not both (the API will automatically calculate the missing
field).

For portrait videos that contain horizontal ASR and rotation metadata,
provide the height, in pixels, per the horizontal ASR. The API calculates
the width per the horizontal ASR. The API detects any rotation metadata
and swaps the requested height and width for the output.

=item * C<< $msg->column_count() >> / C<< $msg->column_count($value) >>

Type: C<Int32>

The maximum number of sprites per row in a sprite sheet. The default is 0,
which indicates no maximum limit.

=item * C<< $msg->row_count() >> / C<< $msg->row_count($value) >>

Type: C<Int32>

The maximum number of rows per sprite sheet. When the sprite sheet is full,
a new sprite sheet is created. The default is 0, which indicates no maximum
limit.

=item * C<< $msg->start_time_offset() >> / C<< $msg->start_time_offset($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

Start time in seconds, relative to the output file timeline. Determines the
first sprite to pick. The default is `0s`.

=item * C<< $msg->end_time_offset() >> / C<< $msg->end_time_offset($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

End time in seconds, relative to the output file timeline. When
`end_time_offset` is not specified, the sprites are generated until the end
of the output file.

=item * C<< $msg->total_count() >> / C<< $msg->total_count($value) >>

Type: C<Int32>

Total number of sprites. Create the specified number of sprites
distributed evenly across the timeline of the output media. The default
is 100.

=item * C<< $msg->interval() >> / C<< $msg->interval($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

Starting from `0s`, create sprites at regular intervals. Specify the
interval value in seconds.

=item * C<< $msg->quality() >> / C<< $msg->quality($value) >>

Type: C<Int32>

The quality of the generated sprite sheet. Enter a value between 1
and 100, where 1 is the lowest quality and 100 is the highest quality.
The default is 100. A high quality value corresponds to a low image data
compression ratio.

=back

