=head2 Google::Cloud::Video::Transcoder::V1::Resources::AudioStream

Audio stream resource.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->codec() >> / C<< $msg->codec($value) >>

Type: C<String>

The codec for this audio stream. The default is `aac`.

Supported audio codecs:

- `aac`
- `aac-he`
- `aac-he-v2`
- `mp3`
- `ac3`
- `eac3`
- `vorbis`

=item * C<< $msg->bitrate_bps() >> / C<< $msg->bitrate_bps($value) >>

Type: C<Int32>

Required. Audio bitrate in bits per second. Must be between 1 and
10,000,000.

=item * C<< $msg->channel_count() >> / C<< $msg->channel_count($value) >>

Type: C<Int32>

Number of audio channels. Must be between 1 and 6. The default is 2.

=item * C<< $msg->channel_layout() >> / C<< $msg->channel_layout($value) >>

Type: C<String>

A list of channel names specifying layout of the audio channels.
This only affects the metadata embedded in the container headers, if
supported by the specified format. The default is `["fl", "fr"]`.

Supported channel names:

- `fl` - Front left channel
- `fr` - Front right channel
- `sl` - Side left channel
- `sr` - Side right channel
- `fc` - Front center channel
- `lfe` - Low frequency

=item * C<< $msg->mapping() >> / C<< $msg->mapping($value) >>

Type: C<Message> (L<Google::Cloud::Video::Transcoder::V1::Resources::AudioStream::AudioMapping>)

The mapping for the
[JobConfig.edit_list][google.cloud.video.transcoder.v1.JobConfig.edit_list]
atoms with audio
[EditAtom.inputs][google.cloud.video.transcoder.v1.EditAtom.inputs].

=item * C<< $msg->sample_rate_hertz() >> / C<< $msg->sample_rate_hertz($value) >>

Type: C<Int32>

The audio sample rate in Hertz. The default is 48000 Hertz.

=item * C<< $msg->language_code() >> / C<< $msg->language_code($value) >>

Type: C<String>

The BCP-47 language code, such as `en-US` or `sr-Latn`. For more
information, see
https://www.unicode.org/reports/tr35/#Unicode_locale_identifier. Not
supported in MP4 files.

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

The name for this particular audio stream that
will be added to the HLS/DASH manifest. Not supported in MP4 files.

=back

